<?php declare(strict_types=1); namespace Tests\Unit\Review; use App\Application\Review\DTO\Request\CreateOrReuseFlashcardRequestDto;use App\Application\Review\Service\CreateOrReuseFlashcardService;use App\Domain\Review\Entity\Flashcard;use App\Domain\Review\Enum\FlashcardSource;use App\Domain\Review\Enum\FlashcardType;use App\Domain\Review\Repository\FlashcardRepositoryInterface;use App\Domain\Review\ValueObject\FlashcardFingerprint;use App\Domain\Taxonomy\Entity\TaxonomySubject;use App\Domain\Taxonomy\Repository\TaxonomySubjectRepositoryInterface;use PHPUnit\Framework\TestCase;final class CreateOrReuseFlashcardServiceTest extends TestCase {public function testReusesExistingCardWithNormalizedFingerprint():void{$now=new \DateTimeImmutable('2026-01-01T10:00:00Z');$subject=new TaxonomySubject('subject',null,'Direito','direito',null,0,true);$fingerprint=FlashcardFingerprint::fromContent('subject',FlashcardType::BASIC,'HTTP   Status',' resposta ');$existing=new Flashcard('card','subject',FlashcardType::BASIC,'HTTP Status','resposta',$fingerprint,FlashcardSource::SYSTEM,$now,$now,['subject']);$cards=$this->createMock(FlashcardRepositoryInterface::class);$cards->expects(self::once())->method('findByFingerprint')->willReturn($existing);$cards->expects(self::never())->method('save');$subjects=$this->createMock(TaxonomySubjectRepositoryInterface::class);$subjects->expects(self::once())->method('findById')->with('subject')->willReturn($subject);$service=new CreateOrReuseFlashcardService($cards,$subjects);self::assertSame($existing,$service->execute(new CreateOrReuseFlashcardRequestDto('subject',' http status ','Resposta'),$now));}}
